#include <iostream>
using namespace std;

int calls = 0;

int next() {
    calls = calls + 1;
    return calls;
}

#define TWICE_M(x) ((x) + (x))

int twice_f(int x) {
    return x + x;
}

int main() {
    cin >> calls;

    cout << "{tag}：" << TWICE_M(next()) << endl;
    cout << calls << endl;
    cout << "招式：" << twice_f(next()) << endl;
    cout << calls << endl;
    return 0;
}
